import type { WidgetServerContext } from "@homarr/widget-sdk/server";
type NamedQuery = {name:string;label?:string;sql:string};
type Cell = null|string|number;
import { DatabaseSync } from "node:sqlite";
import { open } from "node:fs/promises";
import { defineWidgetServer, getWidgetConnection, getWidgetServerContext } from "@homarr/widget-sdk/server";

const databaseSettings = async (context:WidgetServerContext) => {
  const {configuration} = await getWidgetConnection(context,{connection:"database",serviceType:"sqlite"});
  const settings = configuration.settings ?? {};
  if (typeof settings.path !== "string" || !settings.path.trim()) throw new Error("Set path on the SQLite service connection to a mounted database file");
  if (!Array.isArray(settings.queries) || !settings.queries.length) throw new Error("Configure named queries on the SQLite service: queries:[{name,label,sql}]");
  const queries = settings.queries.filter((query:unknown): query is NamedQuery => Boolean(query && typeof query === "object" && "name" in query && typeof query.name === "string" && "sql" in query && typeof query.sql === "string" && (!("label" in query) || typeof query.label === "string")));
  if (!queries.length) throw new Error("At least one named SQL query is required");
  return {path:settings.path,queries};
};
const jsonValue = (value:null|string|number|bigint|Uint8Array):Cell => {
  if (typeof value === "bigint") return String(value);
  if (value instanceof Uint8Array) return `[${value.byteLength} binary bytes]`;
  return value;
};
export default defineWidgetServer({
  catalog: async (_input,context) => {
    const settings = await databaseSettings(context);
    return settings.queries.map((query) => ({value:query.name,label:query.label || query.name}));
  },
  rows: async (input:{name?:string},context) => {
    const settings = await databaseSettings(context);
    const query = settings.queries.find((query) => query.name === input?.name);
    if (!query) throw new Error("Choose a configured query");
    const {options} = await getWidgetServerContext(context);
    const limit = Math.max(1,Math.min(200,Number(options.rowLimit)||100));
    const database = new DatabaseSync(settings.path,{readOnly:true,timeout:1000,allowExtension:false});
    try {
      const statement = database.prepare(query.sql);
      statement.setReadBigInts(true);
      const rows: Record<string,Cell>[] = [];
      let truncated = false;
      for (const row of statement.iterate()) {
        context.signal.throwIfAborted();
        if (rows.length >= limit) { truncated = true; break; }
        rows.push(Object.fromEntries(Object.entries(row).map(([key,value]) => [key,jsonValue(value)])));
      }
      return {rows,columns:statement.columns().map((column) => column.name),truncated,updatedAt:new Date().toISOString()};
    } finally { database.close(); }
  },
  status: async (_input,context) => {
    const {bindingNames} = await getWidgetServerContext(context);
    if (!bindingNames.includes("status")) return {configured:false};
    const {configuration} = await getWidgetConnection(context,{connection:"status",serviceType:"file"});
    const path = configuration.settings?.path;
    if (typeof path !== "string") throw new Error("Set path on the local file connection");
    const file = await open(path,"r");
    try {
      const stat = await file.stat();
      if (!stat.isFile() || stat.size > 524288) throw new Error("Choose a regular JSON status file under 512 KiB");
      const bytes = Buffer.alloc(524289);
      const {bytesRead} = await file.read(bytes,0,bytes.length,0);
      if (bytesRead > 524288) throw new Error("The status file exceeds 512 KiB");
      return {configured:true,value:JSON.parse(bytes.subarray(0,bytesRead).toString("utf8")),updatedAt:stat.mtime.toISOString()};
    } finally { await file.close(); }
  },
});

