type Row = Record<string,null|string|number> & {__row:number};
import type server from "./server";
import { Alert, Badge, Button, Group, Select, Stack, Text } from "@mantine/core";
import { useWidgetHost, useWidgetServices, useWidgetOptions, useWidgetQuery, useWidgetState } from "@homarr/widget-sdk";
import { HomarrDataTable } from "@homarr/widget-sdk/ui";
export default function DatabaseDashboard() {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const options = useWidgetOptions<{title:string;rowLimit:number}>();
  const [selected,setSelected] = useWidgetState("query","");
  const catalog = useWidgetQuery<Awaited<ReturnType<typeof server.catalog>>>("catalog",{}, {staleTime:60000});
  const name = selected || catalog.data?.[0]?.value || "";
  const rows = useWidgetQuery<Awaited<ReturnType<typeof server.rows>>>("rows",{name},{enabled:Boolean(name),refetchInterval:30000});
  const status = useWidgetQuery<Awaited<ReturnType<typeof server.status>>>("status",{}, {refetchInterval:30000});
  const error = catalog.error || rows.error;
  const records:Row[] = (rows.data?.rows ?? []).map((row,index) => ({...row,__row:index}));
  let visible = records.slice(0,10);
  if (host.displayMode === "advanced") visible = records;
  return <Stack h="100%" gap="xs" p="sm">
    <Group justify="space-between"><Text fw={600}>{options.title}</Text><Badge variant="light">Read only</Badge></Group>
    <Select aria-label="Configured database query" data={catalog.data ?? []} value={name || null} onChange={(value) => setSelected(value || "")} />
    {error && <Alert color="red">{error.message}</Alert>}
    <div style={{flex:1,minHeight:0}}><HomarrDataTable<Row> isEditMode={host.isEditMode} cellPadding="6px" idAccessor="__row" records={visible} fetching={rows.isFetching} minHeight={100} columns={(rows.data?.columns ?? []).map((key) => ({accessor:key,title:key,resizable:true,render:(row:Row) => <Text size="xs" lineClamp={2}>{String(row[key] ?? "—")}</Text>}))} noRecordsText="This query has no rows" /></div>
    <Group justify="space-between"><Text size="xs" c="dimmed">{records.length} rows{rows.data?.truncated ? " · row limit reached" : ""}</Text>{host.displayMode !== "advanced" && <Button size="compact-xs" variant="subtle" onClick={() => services.openAdvanced()}>Explore rows</Button>}</Group>
    {status.error && <Alert color="yellow">Status file: {status.error.message}</Alert>}
    {status.data?.configured && <Text component="pre" size="xs" style={{whiteSpace:"pre-wrap",maxHeight:100,overflow:"auto"}}>{JSON.stringify(status.data.value,null,2).slice(0,4000)}</Text>}
  </Stack>;
}
